 private void openLast(){String uri=getSharedPreferences("downloads",0).getString("last_uri","");if(uri.isEmpty()){status.setText("Nenhum download concluído ainda.");return;}String mime=getSharedPreferences("downloads",0).getString("last_mime","video/mp4");if(mime.startsWith("audio/")){DownloadedAudio.remember(this,uri,getSharedPreferences("downloads",0).getString("last_title","Áudio baixado"),mime);if(playbackConnection!=null)androidx.media3.session.MediaController.releaseFuture(playbackConnection);playbackConnection=new androidx.media3.session.MediaController.Builder(this,new androidx.media3.session.SessionToken(this,new ComponentName(this,PlaybackService.class))).buildAsync();playbackConnection.addListener(()->{if(isDestroyed())return;try{androidx.media3.session.MediaController player=playbackConnection.get();androidx.media3.common.MediaItem item=new androidx.media3.common.MediaItem.Builder().setUri(Uri.parse(uri)).setMediaId(DownloadedAudio.id(uri)).setMediaMetadata(new androidx.media3.common.MediaMetadata.Builder().setTitle(getSharedPreferences("downloads",0).getString("last_title","Áudio baixado no Onda Música")).setArtist("Download local").build()).build();player.setMediaItem(item);player.prepare();player.play();startActivity(new Intent(this,MainActivity.class));}catch(Exception e){status.setText("Não foi possível abrir o áudio. Confira se o arquivo ainda existe.");}},handler::post);return;}Intent i=new Intent(Intent.ACTION_VIEW).setDataAndType(Uri.parse(uri),mime).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);if(mime.startsWith("video/"))i.setClass(this,VideoActivity.class);try{startActivity(i);}catch(Exception e){status.setText("Abra o arquivo pelo gerenciador de arquivos do celular.");}}
